const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Coordinates for Aleppo, Syria: ~36.20 N, 37.15 E
    const aleppoPoint = ee.Geometry.Point(37.15, 36.20);
    // Create a buffered region around Aleppo to capture the city area
    const geometry = aleppoPoint.buffer(20000); // 20 km buffer

    const year2012 = '2012';
    const year2016 = '2016';
    const bandName = 'stable_lights';

    // 2. Data Acquisition & Check
    const collection = ee.ImageCollection('NOAA/DMSP-OLS/NIGHTTIME_LIGHTS_V4');

    // Filter for 2012
    let img2012 = collection.filter(ee.Filter.calendarRange(parseInt(year2012), parseInt(year2012), 'year'))
      .select(bandName);

    if (img2012.size().getInfo() === 0) {
      console.log(`No DMSP-OLS images found for ${year2012}.`);
      console.log('C1');
      return;
    }
    img2012 = img2012.first(); // Get the annual composite for 2012

    // Filter for 2016
    let img2016 = collection.filter(ee.Filter.calendarRange(parseInt(year2016), parseInt(year2016), 'year'))
      .select(bandName);

    if (img2016.size().getInfo() === 0) {
      console.log(`No DMSP-OLS images found for ${year2016}.`);
      console.log('C1');
      return;
    }
    img2016 = img2016.first(); // Get the annual composite for 2016

    // 3. Processing & Calculation
    // Define a scale for reduction (DMSP-OLS resolution is ~1km, use 1000m)
    const scale = 1000;

    // Calculate mean light intensity and pixel count for 2012
    const stats2012 = img2012.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326', // DMSP-OLS is in WGS84
      crsTransform: [1, 0, 0, 0, 1, 0] // Ensure original projection if needed, though for mean, it often reprojects.
    }).getInfo();

    const mean2012 = stats2012 ? stats2012[`${bandName}_mean`] : null;
    const count2012 = stats2012 ? stats2012[`${bandName}_count`] : 0;

    // Validate 2012 calculation
    if (count2012 === 0) {
      console.log(`No valid pixels found for 2012 in the specified region. Pixels: ${count2012}`);
      console.log('C2');
      return;
    }
    if (mean2012 === null || isNaN(mean2012)) {
      console.log(`Calculation failure for 2012. Mean: ${mean2012}`);
      console.log('C3');
      return;
    }

    // Calculate mean light intensity and pixel count for 2016
    const stats2016 = img2016.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326',
      crsTransform: [1, 0, 0, 0, 1, 0]
    }).getInfo();

    const mean2016 = stats2016 ? stats2016[`${bandName}_mean`] : null;
    const count2016 = stats2016 ? stats2016[`${bandName}_count`] : 0;

    // Validate 2016 calculation
    if (count2016 === 0) {
      console.log(`No valid pixels found for 2016 in the specified region. Pixels: ${count2016}`);
      console.log('C2');
      return;
    }
    if (mean2016 === null || isNaN(mean2016)) {
      console.log(`Calculation failure for 2016. Mean: ${mean2016}`);
      console.log('C3');
      return;
    }

    // 4. Comparison and Final Answer
    console.log(`Aleppo (${year2012}) Mean NTL: ${mean2012.toFixed(2)} (Pixels: ${count2012})`);
    console.log(`Aleppo (${year2016}) Mean NTL: ${mean2016.toFixed(2)} (Pixels: ${count2016})`);

    if (mean2016 < mean2012) {
      console.log('A'); // Yes, it decreased
    } else {
      console.log('B'); // No, it did not decrease (stayed same or increased)
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    console.log('D'); // General error / memory issue / syntax
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
